#!/usr/bin/env python3
"""Writes docs/format-icon-coverage.md from docs/format-icon-coverage.json.

  python3 scripts/format-icon-coverage.py          # rewrite the page
  python3 scripts/format-icon-coverage.py --check  # fail if it is out of date
"""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'docs/format-icon-coverage.json'
PAGE = ROOT / 'docs/format-icon-coverage.md'


def render(data):
    lines = ['# Archive format and document icon coverage', '',
             '<!-- Generated by `python3 scripts/format-icon-coverage.py` from docs/format-icon-coverage.json. Do not edit. -->', '',
             'Arkiv identifies archives by their content. A name only chooses the icon, the',
             'suffix of a new archive, and which files form a split 7z set. This table is enforced by',
             '`tests/test_format_icon_coverage.py` and `Tests/ArkivThemesTests/DocumentIconArtworkTests.swift`.', '',
             '* **Finder icon** is what Finder draws **when Arkiv is the default app for that type**',
             '  (Get Info → Open with → Change All). Otherwise Finder draws the default app\'s icon.',
             '  Finder types a file by its last extension only.',
             '* **Inside Arkiv** is the artwork Arkiv\'s own windows use (archive rows, title bar, Archive',
             '  Info, Settings previews) for the selected document icon theme. Names are matched case-insensitively,',
             '  longest suffix first.', '',
             '| Name | Format | Engine | Created as | Finder type | Finder icon | Inside Arkiv | Status |',
             '| --- | --- | --- | --- | --- | --- | --- | --- |']
    labels = data['statuses']
    for row in data['rows']:
        cells = [f"`{row['name']}`", row['format'], row['engine'], f"`{row['create']}`" if row['create'] else '—',
                 f"`{row['finderType']}`" if row['finderType'] else 'none (dynamic type, never claimed)',
                 row['finderIcon'] or 'system icon', row['inApp'] or 'system icon', labels[row['status']]]
        lines.append('| ' + ' | '.join(cells) + ' |')
        if row.get('note'):
            lines[-1] = lines[-1][:-2] + f" — {row['note']} |"
    lines += ['', 'Uppercase and mixed-case names (`ARCHIVE.ZIP`, `Archive.Tar.Xz`) map exactly like lowercase ones.', '']
    return '\n'.join(lines)


if __name__ == '__main__':
    text = render(json.loads(SOURCE.read_text()))
    if '--check' in sys.argv:
        if PAGE.read_text() != text:
            raise SystemExit('docs/format-icon-coverage.md is out of date')
    else:
        PAGE.write_text(text)
